# 接口面跨多个公共头（netsys_client.h 的 Poll 族 + DNS resolver client 头的 NetSys* 族）。
# 消费方：netstack(libhttp_client/libhttp/libcurl_shared_http3)、appspawn(DisallowInternet)、
# netsys_native_manager。文件内全局数据 g_dnsReport* / g_lastDnsQueryPollSendTime 未在任何
# 头文件声明，属实现细节，予以隐藏。
{
  global:
    extern "C" {
      addr_to_string;
      DisallowInternet;
      FillBasicAddrInfo;
      FillBasicDnsServerInfo;
      FillDnsServerInfo;
      FillQueryParam;
      GetQueryFailCause;
      HandleQueryAbnormalReport;
      IsAllCname;
      IsAllNoAnswer;
      IsAllowInternet;
      IsFailCauseAllowedReport;
      IsLoopbackAddr;
      IsSystemUid;
      MakeDefaultDnsServer;
      MakeNonBlock;
      NetsysPostDnsAbnormal;
      NetSysBindSocket;
      NetSysGetDefaultNetwork;
      NetSysGetNodataCache;
      NetSysGetResolvCache;
      NetSysGetResolvConf;
      NetSysGetResolvConfExt;
      NetSysIsIpv4Enable;
      NetSysIsIpv6Enable;
      NetSysPostDnsQueryResult;
      NetSysPostDnsResult;
      NetSysSetNodataCache;
      NetSysSetResolvCache;
      Poll;
      PollRecvData;
      PollSendData;
    };
  local:
    *;
};
